mapper.select:
SELECT
    src.${regionColumn} AS region_id,
    COUNT(tl.id) AS count
FROM topology_links tl
JOIN network_elements src ON src.id = tl.source_id
JOIN network_elements tgt ON tgt.id = tl.target_id
JOIN regions r ON r.id = src.${regionColumn}
WHERE r.level = #{level}
  AND r.geom && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326)
  AND src.${regionColumn} = tgt.${regionColumn}
  AND (#{types}::text[] IS NULL OR (src.type = ANY(#{types}::text[]) AND tgt.type = ANY(#{types}::text[])))
  AND (#{propFilter}::text IS NULL OR (src.properties @> #{propFilter}::jsonb AND tgt.properties @> #{propFilter}::jsonb))
GROUP BY src.${regionColumn}
ORDER BY src.${regionColumn}

SELECT
    LEAST(src.${regionColumn}, tgt.${regionColumn}) AS source_region_id,
    GREATEST(src.${regionColumn}, tgt.${regionColumn}) AS target_region_id,
    COUNT(tl.id) AS count
FROM topology_links tl
JOIN network_elements src ON src.id = tl.source_id
JOIN network_elements tgt ON tgt.id = tl.target_id
JOIN regions source_region ON source_region.id = src.${regionColumn}
JOIN regions target_region ON target_region.id = tgt.${regionColumn}
WHERE source_region.level = #{level}
  AND target_region.level = #{level}
  AND source_region.geom && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326)
  AND target_region.geom && ST_MakeEnvelope(#{west}, #{south}, #{east}, #{north}, 4326)
  AND src.${regionColumn} <> tgt.${regionColumn}
  AND (#{types}::text[] IS NULL OR (src.type = ANY(#{types}::text[]) AND tgt.type = ANY(#{types}::text[])))
  AND (#{propFilter}::text IS NULL OR (src.properties @> #{propFilter}::jsonb AND tgt.properties @> #{propFilter}::jsonb))
GROUP BY LEAST(src.${regionColumn}, tgt.${regionColumn}), GREATEST(src.${regionColumn}, tgt.${regionColumn})
ORDER BY count DESC, source_region_id, target_region_id
LIMIT #{limit}
